import { useMemo, useState } from 'react';

import { useOverlaysEvents } from '../../core/hooks/useOverlaysEvents.js';
import { MouseCoordinate } from '../../core/types/overlays.js';
import { nodePadding } from '../functions/node-padding.js';
import {
  useTooltipPinnedState,
  useVisibleNodesState,
} from '../store/selectors.js';

export const useTooltipItemDataEntry = () => {
  const pinned = useTooltipPinnedState();
  const visibleNodes = useVisibleNodesState();
  const events = useOverlaysEvents();
  const newMousePos = events.mousePosition;
  const [plotMousePosition, setPlotMousePosition] = useState<
    MouseCoordinate | undefined
  >(newMousePos);

  if (!pinned && plotMousePosition !== newMousePos) {
    setPlotMousePosition(newMousePos);
  }

  return useMemo(() => {
    const pos: MouseCoordinate = plotMousePosition ?? { x: -100, y: -100 };

    return visibleNodes.find((node) => {
      const padding = nodePadding(node);

      return (
        node.x0 - padding <= pos.x &&
        node.x1 + padding >= pos.x &&
        node.y0 - padding <= pos.y &&
        node.y1 + padding >= pos.y
      );
    });
  }, [visibleNodes, plotMousePosition]);
};
